mapper.insert:
/* insertMember */
INSERT INTO tb_user(
    user_id
    , password
    , nm
    , `role`
    , email
    , phone
    , delete_at
)
VALUES (
    #{userId}
    , #{password}
    , #{nm}
    , #{role}
    , #{email}
    , #{phone}
    , #{deleteAt}
)

mapper.select:
/* isOwner */
SELECT
    IF(COUNT(*), 1, 0)
FROM tb_user tu
WHERE
    tu.role = 'OWNER'
    AND tu.user_id = #{value}
    AND tu.delete_at = 'N';

mapper.update:
/* updateMember */
UPDATE tb_user SET
    updated_at = NOW()

        , nm = #{nm}


        , `role` = #{role}


        , email = #{email}


        , phone = #{phone}


        , delete_at = #{deleteAt}

WHERE
    idx = #{idx}
